using Marketplace.Domain.Common; namespace Marketplace.Domain.Orders; public sealed class Order:AggregateRoot<long>{private readonly List<OrderItem> _items=[];private Order(){} public string OrderNumber{get;private set;}=null!;public long CustomerId{get;private set;}public long StoreId{get;private set;}public long CartId{get;private set;}public OrderStatus Status{get;private set;}public long SubTotalIRR{get;private set;}public long CampaignDiscountIRR{get;private set;}public long DirectDiscountIRR{get;private set;}public long CouponDiscountIRR{get;private set;}public long WarrantyAmountIRR{get;private set;}public long ShippingGrossIRR{get;private set;}public long ShippingBenefitIRR{get;private set;}public long ShippingAmountIRR{get;private set;}public long TotalAmountIRR{get;private set;}public long? CouponId{get;private set;}public string? CouponCodeSnapshot{get;private set;}public DateTime CreatedAtUtc{get;private set;}public DateTime UpdatedAtUtc{get;private set;}public IReadOnlyCollection<OrderItem> Items=>_items.AsReadOnly(); public static Order Create(long id,string number,long customerId,long storeId,long cartId,long sub,long camp,long direct,long coupon,long warranty,long shipGross,long shipBenefit,long ship,long total,long? couponId,string? couponCode){if(string.IsNullOrWhiteSpace(number)||sub<0||camp<0||direct<0||coupon<0||warranty<0||shipGross<0||shipBenefit<0||ship<0||total<0)throw new DomainException("Invalid order.");var expected=sub-camp-direct-coupon+warranty+ship;if(total!=expected)throw new DomainException("Order total mismatch.");var n=DateTime.UtcNow;return new(){Id=id,OrderNumber=number,CustomerId=customerId,StoreId=storeId,CartId=cartId,Status=OrderStatus.PendingPayment,SubTotalIRR=sub,CampaignDiscountIRR=camp,DirectDiscountIRR=direct,CouponDiscountIRR=coupon,WarrantyAmountIRR=warranty,ShippingGrossIRR=shipGross,ShippingBenefitIRR=shipBenefit,ShippingAmountIRR=ship,TotalAmountIRR=total,CouponId=couponId,CouponCodeSnapshot=couponCode,CreatedAtUtc=n,UpdatedAtUtc=n};}public void AddItem(OrderItem x){_items.Add(x);Touch();}public void MarkPaid(){Require(OrderStatus.PendingPayment);Status=OrderStatus.Paid;Touch();}public void StartPreparing(){Require(OrderStatus.Paid);Status=OrderStatus.Preparing;Touch();}public void MarkReadyForDelivery(){Require(OrderStatus.Preparing);Status=OrderStatus.ReadyForDelivery;Touch();}public void MarkDelivered(){Require(OrderStatus.ReadyForDelivery);Status=OrderStatus.Delivered;Touch();}public void Complete(){Require(OrderStatus.Delivered);Status=OrderStatus.Completed;Touch();}public void Cancel(){if(Status is OrderStatus.Completed or OrderStatus.Refunded)throw new DomainException("Order cannot be cancelled.");Status=OrderStatus.Cancelled;Touch();}public void MarkDeliveryExpired(){Require(OrderStatus.ReadyForDelivery);Status=OrderStatus.DeliveryExpired;Touch();}public void OpenDispute(){if(Status is not(OrderStatus.Delivered or OrderStatus.Completed))throw new DomainException("Invalid dispute state.");Status=OrderStatus.Disputed;Touch();}public void RequestRefund(){if(Status is not(OrderStatus.Delivered or OrderStatus.Completed or OrderStatus.Disputed))throw new DomainException("Invalid refund state.");Status=OrderStatus.RefundRequested;Touch();}public void MarkRefunded(){Status=OrderStatus.Refunded;Touch();}public void MarkPartiallyRefunded(){Status=OrderStatus.PartiallyRefunded;Touch();}private void Require(OrderStatus s){if(Status!=s)throw new DomainException($"Order must be {s}.");}private void Touch()=>UpdatedAtUtc=DateTime.UtcNow;}
